SUFFIXES = {"__scenario_a": " (Scenario A)", "__scenario_b": " (Scenario B)", "__original_rows": " (original_rows view)", "__exact_distinct_rows": " (exact_distinct_rows view)"}


def describe(column: str) -> str | None:
    if column in BASE:
        return BASE[column]
    for suffix, label in SUFFIXES.items():
        if column.endswith(suffix):
            stem = column[: -len(suffix)]
            stem = {"n_pr_lines": "n_lines"}.get(stem, stem)
            if stem in BASE:
                return BASE[stem] + label
    return None
